import { Component, forwardRef, Input, OnInit } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';

@Component({
	selector: 'espd-text-area',
	templateUrl: './text-area.component.html',
	styleUrls: ['./text-area.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => TextAreaComponent) }],
	standalone: false
})
export class TextAreaComponent extends EspdAbstractSizeableInputDirective implements OnInit {

	@Input() public rows?: number = 5;
	@Input() public maxLength?: number;

	ngOnInit(): void {
		super.ngOnInit();
		if (this.maxLength) {
			this.errorMessages.maxlength = ['common.validation.maxLength', this.maxLength];
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}