import { Component, forwardRef, Input } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective } from 'espd-common/forms/api';
import { MessageConfig } from 'espd-common/i18n';

export interface RadioOption {
	value: any;
	label: MessageConfig | string;
	disabled?: boolean;
}

@Component({
	selector: 'espd-radio',
	templateUrl: './radio.component.html',
	styleUrls: ['./radio.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => RadioComponent) }],
	standalone: false,
	host: {
		'[class.horizontal]': 'isHorizontal'
	},
})
export class RadioComponent extends EspdAbstractInputDirective {
	@Input() public options!: RadioOption[];
	@Input() public layoutDirection: 'horizontal' | 'vertical' = 'vertical';

	public get isHorizontal(): boolean {
		return this.layoutDirection === 'horizontal';
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}