import { Component, forwardRef, Input, OnChanges, OnInit, SimpleChanges, TemplateRef } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractInputDirective, EspdFormControl } from 'espd-common/forms/api';
import { MessageConfig } from 'espd-common/i18n';

export type CheckboxLabel = MessageConfig | string | TemplateRef<any>;

export interface CheckboxOption {
	control: EspdFormControl;
	label: CheckboxLabel;
	disabled?: boolean;
}

@Component({
	selector: 'espd-checkbox',
	templateUrl: './checkbox.component.html',
	styleUrls: ['./checkbox.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => CheckboxComponent) }],
	standalone: false
})
export class CheckboxComponent extends EspdAbstractInputDirective implements OnInit, OnChanges {

	@Input() public checkboxLabel?: CheckboxLabel;

	@Input() public options?: CheckboxOption[];

	private singleLabel: CheckboxLabel | null = null;

	public ngOnInit(): void {
		super.ngOnInit();
		this.setSingleControl();
		this.setEnabledDisabled();
	}

	public ngOnChanges(changes: SimpleChanges): void {
		super.ngOnChanges(changes);

		if (changes.checkboxLabel && changes.checkboxLabel.currentValue) {
			this.singleLabel = changes.checkboxLabel.currentValue;
			this.setSingleControl();
		}

		if (changes.disabled || changes.control) {
			this.setSingleControl();
		}
		setTimeout(() => {
			this.setEnabledDisabled();
		});
	}

	public isLabelTemplate(label: CheckboxLabel): label is TemplateRef<any> {
		return label instanceof TemplateRef;
	}

	public isLabelMessage(label: CheckboxLabel): label is string | MessageConfig {
		return typeof label === 'string' || this.instanceOfMessageConfig(label);
	}

	private setEnabledDisabled() {
		this.options?.forEach(option => {
			if (option.disabled && option.control.enabled) {
				option.control.disable();
			} else if (!option.disabled && !option.control.enabled) {
				option.control.enable();
			}
		});
	}

	private setSingleControl() {
		if (this.control && this.singleLabel) {
			this.options = [{ control: this.control, label: this.singleLabel!, disabled: this.disabled }];
		}
	}

	private instanceOfMessageConfig(object: any): object is MessageConfig {
		return 'key' in object;
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}