import { Component, forwardRef, Input, OnDestroy, OnInit } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';
import { Subscription } from 'rxjs';

@Component({
	selector: 'espd-range-slider',
	templateUrl: './range-slider.component.html',
	styleUrls: ['./range-slider.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => RangeSliderComponent) }],
	standalone: false
})
export class RangeSliderComponent extends EspdAbstractSizeableInputDirective implements OnInit, OnDestroy {

	private valueSubscription?: Subscription;

	@Input() public valueSuffix!: string;
	@Input() public min!: number;
	@Input() public max!: number;
	@Input() public step: number = 1;

	ngOnInit(): void {
		super.ngOnInit();
		this.setControl();
	}

	public ngOnDestroy(): void {
		if (this.valueSubscription) {
			this.valueSubscription.unsubscribe();
		}
	}

	private setControl() {
		if (this.valueSubscription) {
			this.valueSubscription.unsubscribe();
		}
		if (this.control) {
			// because the formcontrol is bound to more than one input, re-set the value when one changes to update the rendered view of the other
			this.valueSubscription = this.control.valueChanges.subscribe(value => {
				this.control.setValue(value, { emitEvent: false });
			});
		}
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}