import { Component, ElementRef, forwardRef, Input, OnInit, ViewChild } from '@angular/core';
import { espdAbstractInputComponentInjectionToken, EspdAbstractSizeableInputDirective } from 'espd-common/forms/api';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';

type InputMode = 'none' | 'text' | 'decimal' | 'numeric' | 'tel' | 'search' | 'email' | 'url';

@Component({
	selector: 'espd-input',
	templateUrl: './input.component.html',
	styleUrls: ['./input.component.scss'],
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => InputComponent) }],
	standalone: false
})
export class InputComponent extends EspdAbstractSizeableInputDirective implements OnInit {

	@Input() public type: string = 'text';
	@Input() public maxLength?: number;
	@Input() public inputMode?: InputMode;
	@Input() public min?: string;
	@Input() public max?: string;
	@Input() public step?: number;
	@Input() public mask?: string;

	@ViewChild(InputScaffoldComponent, { read: ElementRef })
	protected scaffoldElement?: ElementRef;

	@ViewChild('input')
	private inputElement?: ElementRef;

	ngOnInit(): void {
		super.ngOnInit();
		if (this.maxLength) {
			this.errorMessages.maxlength = ['common.validation.maxLength', this.maxLength];
		}
	}

	public focus(target: 'control' | 'container' = 'control'): void {
		(target === 'control'
			? this.inputElement
			: this.scaffoldElement
		)?.nativeElement.focus();
	}
}